def create_rules(apps, schema_editor):
    Rule = apps.get_model('core', 'NotificationRule')
    Template = apps.get_model('core', 'NotificationTemplate')
    db = schema_editor.connection.alias
    for trigger, texts in DEFAULTS.items():
        rule, created = Rule.objects.using(db).get_or_create(trigger=trigger, defaults={'enabled': False})
        if created:
            Template.objects.using(db).bulk_create([Template(rule=rule, content=text) for text in texts])



